python3 -c "
import json
with open('/app/resources/treasury_bulletin_1939_05.json', 'r') as f:
    data = json.load(f)

# Print the structure
def find_key(obj, key):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if key.lower() in k.lower():
                print(f'Found: {k}')
            if isinstance(v, (dict, list)):
                find_key(v, key)
    elif isinstance(obj, list):
        for item in obj:
            find_key(item, key)

find_key(data, 'cooperative')
